#!/bin/sh
# Copies the licences shipped with a build into directory $1: the program's
# own (GPL-3.0-or-later), the SYRO library's (BSD-3-Clause), the fonts'
# (SIL OFL 1.1) and, generated by cargo-about (about.toml), those of the
# Rust crates compiled into the program. Run from the repository root.
set -eu
mkdir -p "$1"
cp LICENSE "$1/LICENSE"
cp volcasm-syro-sys/vendor/volcasample/COPYING "$1/SYRO-COPYING"
cp volcasm-app/assets/fonts/OFL-*.txt "$1/"
if ! command -v cargo-about >/dev/null 2>&1; then
    echo "cargo-about not found (pacman -S cargo-about or cargo install cargo-about)" >&2
    exit 1
fi
cargo about generate --fail --locked -o "$1/THIRD-PARTY-LICENSES.html" about.hbs
